@group(3) @binding(3) var<storage, read> triangleLookup:  array<u32>;

struct DrawItem {
    firstIndex: u32,
    firstVertex: u32,
    firstTriangle: u32,
    packedInstance: u32,
};

fn unpackInstanceIndex(packed: u32) -> UnpackedInstance {
    var res: UnpackedInstance;
    res.isStroke = (packed & 0x80000000u) != 0u;
    res.isMega   = (packed & 0x40000000u) != 0u;
    res.stateIdx = (packed >> 16u) & 0x3FFFu;
    res.localIdx = packed & 0xFFFFu;
    return res;
}
